// OTOMATİK ÜRETİLİR (_tasarim/araclar/p345-gom.py) — elle düzenleme. GPT Paket 4 savaş efekt şeritleri (12 kare × 24 fps).
// 19 görsel, WebP base64 (1901 KB); ilk kullanımda Blob URL'ye çevrilir.
const D = {
"arc":"",
"blast":"",
"bossEntrance":"",
"burst":"",
"critHit":"",
"crystal":"",
"dissolve":"",
"dome":"",
"drip":"",
"fireball":"",
"flame":"",
"heal":"",
"mote":"",
"orb":"",
"orbit":"",
"shard":"",
"shatter":"",
"spark":"",
"zap":"",
};
const U = {};
// Anahtarın Blob URL'si; yoksa null
export const url = k => { if (U[k]) return U[k]; const s = D[k]; if (!s) return null;
  try { const b = atob(s), a = new Uint8Array(b.length); for (let i = 0; i < b.length; i++) a[i] = b.charCodeAt(i); return (U[k] = URL.createObjectURL(new Blob([a], { type: 'image/webp' }))); }
  catch { return (U[k] = 'data:image/webp;base64,' + s); } };
export const KEYS = Object.keys(D);
export const FRAME = 160, FRAMES = 12;
